package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.jsoup.helper.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class XmlDeclaration_getWholeDeclaration_TriageGen0Test {

    /**
     * Helper method to inject attributes into the private field of XmlDeclaration
     * since the provided constructor doesn't show an attributes setter.
     */
    private void setAttributes(XmlDeclaration decl, Map<String, String> attributes) throws Exception {
        Field field = XmlDeclaration.class.getDeclaredField("attributes");
        field.setAccessible(true);
        field.set(decl, attributes);
    }

    @Test
    public void testGetWholeDeclaration_NameNotXml() {
        XmlDeclaration decl = new XmlDeclaration("html", "uri", false);
        // If name is not "xml", it should just return the name regardless of attributes
        assertEquals("html", decl.getWholeDeclaration());
    }










}

