public class XmlDeclaration_getWholeDeclaration_TriageGen0Test {

    /**
     * Helper method to inject attributes into the private field of XmlDeclaration
     * since the provided constructor doesn't show an attributes setter.
     */
    private void setAttributes(XmlDeclaration decl, Map<String, String> attributes) throws Exception {
        Field field = XmlDeclaration.class.getDeclaredField("attributes");
        field.setAccessible(true);
        field.set(decl, attributes);
    }





    @Test
    public void testGetWholeDeclaration_XmlWithTwoAttributes_BothPresent() throws Exception {
        XmlDeclaration decl = new XmlDeclaration("xml", "uri", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", "1.0");
        attributes.put("encoding", "UTF-8");
        setAttributes(decl, attributes);

        // size > 1 and both version/encoding are non-null
        String expected = "xml version=\"1.0\" encoding=\"UTF-8\"";
        assertEquals(expected, decl.getWholeDeclaration());
    }






